import React from 'react';
import { useNavigate } from 'react-router-dom';

export default function LandingPage() {
  const navigate = useNavigate();

  return (
    <div style={{
      backgroundColor: '#000',
      color: '#ffeb3b',
      height: '100vh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      fontFamily: 'Arial, sans-serif'
    }}>
      <h1>Welcome to RISPO</h1>
      <p>Manage your tournaments, players, and matches</p>

      <div style={{ marginTop: '20px' }}>
        <button
          onClick={() => navigate('/register')}
          style={{
            backgroundColor: '#ffeb3b',
            color: '#000',
            padding: '10px 20px',
            border: 'none',
            borderRadius: '5px',
            marginRight: '10px',
            cursor: 'pointer',
            fontWeight: 'bold'
          }}
        >
          Register
        </button>

        <button
          onClick={() => navigate('/login')}
          style={{
            backgroundColor: '#ffeb3b',
            color: '#000',
            padding: '10px 20px',
            border: 'none',
            borderRadius: '5px',
            cursor: 'pointer',
            fontWeight: 'bold'
          }}
        >
          Login
        </button>
      </div>
    </div>
  );
}
